package com.ias.finance;
import com.ias.trust.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import javax.sql.DataSource;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;

/** Public read model assembled from current finance approval plus exact ticket/stock owner facts. */
@RestController
public final class FeeExecutionProjectionController {
 @FunctionalInterface interface Peer{Map<String,Object> call(String edge,String path,Map<String,Object> body,HttpServletRequest request);}
 private final DataSource source;private final FinanceAccess access;private final Peer peer;
 @org.springframework.beans.factory.annotation.Autowired
 public FeeExecutionProjectionController(DataSource source,FinanceAccess access){this(source,access,(e,p,b,r)->{var f=Chain.call(e,p,b,Chain.trace(r),Chain.deadline(r));Chain.fresh(f,Chain.deadline(r));return f;});}
 FeeExecutionProjectionController(DataSource source,FinanceAccess access,Peer peer){this.source=source;this.access=access;this.peer=peer;}
 @GetMapping("/api/finance/groups/{group}/fee-execution-projection") Map<String,Object> projection(@PathVariable String group,@RequestParam String completionId,HttpServletRequest r)throws Exception{
  UUID groupId=FinanceController.id(group),completion=FinanceController.id(completionId);var principal=access.feePrincipal(r);var store=new JdbcFeeGroups(source,access.feeBind(r,principal));var owner=store.owner(principal.actor(),groupId);var current=store.read(principal.actor(),owner);
  Map<String,Object> row;try(var c=source.getConnection();var q=JdbcMoneyLedger.query(c,"SELECT m.*,q.quote_json FROM finance_approval_completion_mirror m JOIN finance_quote_version q ON q.tenant_id=m.tenant_id AND q.application_id=m.quote_id WHERE m.tenant_id=? AND m.customer_company_id=? AND m.fault_group_id=? AND m.completion_id=?",owner.tenantId(),owner.customerCompanyId(),group,completionId);var rs=q.executeQuery()){if(!rs.next())throw new Problem(404,"FEE_COMPLETION_NOT_FOUND");row=new HashMap<>();var md=rs.getMetaData();for(int i=1;i<=md.getColumnCount();i++)row.put(md.getColumnLabel(i).toLowerCase(java.util.Locale.ROOT),rs.getObject(i));}
  var quote=FinanceController.JSON.readValue(row.get("quote_json").toString(),JdbcFeeGroups.QuoteVersion.class);@SuppressWarnings("unchecked")Map<String,Object> fact=FinanceController.JSON.readValue(row.get("fact_json").toString(),Map.class);if(!"COMPLETED".equals(fact.get("state")))throw new Problem(503,"FEE_COMPLETION_NOT_TERMINAL");String generation=positive(fact.get("generation"));
  var details=new TreeMap<String,Map<String,Object>>();for(var line:quote.command().additions()){String kind=quote.details().kinds().get(line.id());var x=new LinkedHashMap<String,Object>();x.put("lineId",line.id().toString());x.put("kind",kind);x.put("approvedAmountCents",Long.toString(line.amountCents()));x.put("ticketId",line.ticketId().toString());x.put("roundId",line.roundId().toString());
   var binding=quote.details().partBindings().get(line.id());
   if(binding!=null)x.put("approvedQuantity",Long.toString(binding.quantity()));
   details.put(line.id().toString(),x);}
  if(fact.get("lines") instanceof List<?> facts)for(Object raw:facts)if(raw instanceof Map<?,?> m&&m.get("id")!=null&&details.containsKey(m.get("id").toString())&&m.get("quantity")!=null){
   var line=details.get(m.get("id").toString());String quantity=positive(m.get("quantity"));
   if(line.containsKey("approvedQuantity")&&!quantity.equals(line.get("approvedQuantity")))throw new Problem(503,"FEE_EXECUTION_FACT_MISMATCH");
   line.put("approvedQuantity",quantity);
  }
  String operation=UUID.nameUUIDFromBytes(("fee-projection:"+owner.tenantId()+":"+group+":"+completionId+":"+generation).getBytes(StandardCharsets.UTF_8)).toString();String digest=sha(Map.of("tenantId",Long.toString(owner.tenantId()),"companyId",Long.toString(owner.customerCompanyId()),"groupId",group,"completionId",completionId,"quoteId",quote.command().applicationId().toString(),"quoteVersion",Long.toString(quote.basis().groupVersion()),"generation",generation));
  var common=new LinkedHashMap<String,Object>();common.put("sessionToken",Chain.cookie(r));common.put("companyId",Long.toString(owner.customerCompanyId()));common.put("groupId",group);common.put("completionId",completionId);common.put("quoteId",quote.command().applicationId().toString());common.put("quoteVersion",Long.toString(quote.basis().groupVersion()));common.put("generation",generation);common.put("operationId",operation);common.put("authorityDigest",digest);
  var labor=lines(details,Set.of("LABOR","OTHER"));var parts=lines(details,Set.of("PART"));if(!labor.isEmpty())apply(owner,"ticket",common,labor,peer(common,labor,"finance-ticket","/internal/ticket/fee-executions/projection",r),details);if(!parts.isEmpty())apply(owner,"stock",common,parts,peer(common,parts,"finance-stock","/internal/stock/finance-part-executions/projection",r),details);
  long approved=0,executed=0;boolean complete=true;for(var x:details.values()){long a=Long.parseLong(x.get("approvedAmountCents").toString()),e=Long.parseLong(x.getOrDefault("executedAmountCents","0").toString());if(e<0||e>a)throw new Problem(503,"FEE_EXECUTION_FACT_MISMATCH");x.put("executedAmountCents",Long.toString(e));x.put("remainingAmountCents",Long.toString(a-e));approved=Math.addExact(approved,a);executed=Math.addExact(executed,e);if(x.containsKey("approvedQuantity")){long aq=Long.parseLong(x.get("approvedQuantity").toString()),eq=Long.parseLong(x.getOrDefault("executedQuantity","0").toString());if(eq<0||eq>aq)throw new Problem(503,"FEE_EXECUTION_FACT_MISMATCH");x.put("executedQuantity",Long.toString(eq));x.put("remainingQuantity",Long.toString(aq-eq));complete&=eq==aq;}complete&=e==a;}
  var out=new LinkedHashMap<String,Object>();out.put("tenantId",Long.toString(owner.tenantId()));out.put("companyId",Long.toString(owner.customerCompanyId()));out.put("groupId",group);out.put("completionId",completionId);out.put("quoteId",quote.command().applicationId().toString());out.put("quoteVersion",Long.toString(quote.basis().groupVersion()));out.put("generation",generation);out.put("factVersion",Long.toString(current.version()));out.put("completionState","COMPLETED");out.put("executionState",complete?"FULLY_EXECUTED":executed==0?"NOT_EXECUTED":"PARTIALLY_EXECUTED");out.put("approvedAmountCents",Long.toString(approved));out.put("executedAmountCents",Long.toString(executed));out.put("remainingAmountCents",Long.toString(approved-executed));out.put("lines",new ArrayList<>(details.values()));return out;
 }
 private Map<String,Object> peer(Map<String,Object> common,List<Map<String,Object>> lines,String edge,String path,HttpServletRequest r){var b=new LinkedHashMap<>(common);b.put("lines",lines.stream().map(x->Map.of("lineId",x.get("lineId"),"amountCents",x.get("approvedAmountCents"),"ticketId",x.get("ticketId"),"roundId",x.get("roundId"),"kind",x.get("kind"))).toList());try{return peer.call(edge,path,b,r);}catch(Problem e){if(e.status==404||e.status>=500)throw new Problem(503,"FEE_EXECUTION_OWNER_UNAVAILABLE");throw e;}catch(RuntimeException e){throw new Problem(503,"FEE_EXECUTION_OWNER_UNAVAILABLE");}}
 private static List<Map<String,Object>> lines(Map<String,Map<String,Object>> all,Set<String> kinds){return all.values().stream().filter(x->kinds.contains(x.get("kind"))).toList();}
 private static void apply(FeeGroup.Identity owner,String source,Map<String,Object> expected,List<Map<String,Object>> requested,Map<String,Object> proof,Map<String,Map<String,Object>> all){
  if(!Long.toString(owner.tenantId()).equals(Objects.toString(proof.get("tenantId"),""))||!Long.toString(owner.customerCompanyId()).equals(Objects.toString(proof.get("companyId"),""))||!"PROJECTION".equals(proof.get("state")))throw new Problem(503,"FEE_EXECUTION_FACT_MISMATCH");
  for(String key:List.of("groupId","completionId","quoteId","quoteVersion","generation","operationId","authorityDigest"))if(!Objects.equals(expected.get(key),proof.get(key)))throw new Problem(503,"FEE_EXECUTION_FACT_MISMATCH");
  if(!(proof.get("items") instanceof List<?> items)||items.size()!=requested.size())throw new Problem(503,"FEE_EXECUTION_FACT_MISMATCH");var wanted=new HashSet<String>();for(var x:requested)wanted.add(x.get("lineId").toString());var seen=new HashSet<String>();
  for(Object raw:items){if(!(raw instanceof Map<?,?> item)||item.get("lineId")==null||!wanted.contains(item.get("lineId").toString())||!seen.add(item.get("lineId").toString())||!all.containsKey(item.get("lineId").toString()))throw new Problem(503,"FEE_EXECUTION_FACT_MISMATCH");var line=all.get(item.get("lineId").toString());if(line.containsKey("ownerSource")||!line.get("kind").equals(item.get("kind"))||!Objects.equals(line.get("ticketId"),item.get("ticketId"))||!Objects.equals(line.get("roundId"),item.get("roundId")))throw new Problem(503,"FEE_EXECUTION_FACT_MISMATCH");line.put("ownerSource",source);boolean empty="NOT_EXECUTED".equals(item.get("state"));if(empty){if(!"0".equals(item.get("amountCents"))||item.get("executionReceiptId")!=null||item.get("quantity")!=null&&!"0".equals(item.get("quantity")))throw new Problem(503,"FEE_EXECUTION_FACT_MISMATCH");line.put("executedAmountCents","0");if(item.get("quantity")!=null)line.put("executedQuantity","0");}else{if(!"EXECUTED".equals(item.get("state")))throw new Problem(503,"FEE_EXECUTION_FACT_MISMATCH");try{line.put("executionReceiptId",UUID.fromString(Objects.toString(item.get("executionReceiptId"),"")).toString());}catch(IllegalArgumentException e){throw new Problem(503,"FEE_EXECUTION_FACT_MISMATCH");}line.put("executedAmountCents",positive(item.get("amountCents")));if(item.get("quantity")!=null)line.put("executedQuantity",positive(item.get("quantity")));}}
 }
 private static String positive(Object v){String x=Objects.toString(v,"");if(!x.matches("[1-9][0-9]{0,18}"))throw new Problem(503,"FEE_EXECUTION_FACT_MISMATCH");return x;}
 private static String sha(Object v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Chain.JSON.writeValueAsBytes(v)));}catch(Exception e){throw new IllegalStateException(e);}}
}
